<script setup>
import {ref,computed,onMounted,onUnmounted,nextTick,watch} from 'vue';
import {Link,usePage,router} from '@inertiajs/vue3';
import Footer from './Footer.vue';import Errors from './Errors.vue';import Avatar from './Avatar.vue';import BadgeCrew from './BadgeCrew.vue';import {art} from '../art';
const page=usePage(),tierDialog=ref(null),header=ref(null),menu=ref(''),accountButton=ref(null),journeyTab=ref('journey');let observer;
const rank=computed(()=>page.props.achievement),community=computed(()=>page.props.community);
function closeMenu(e){if(e.type==='keydown'&&e.key!=='Escape')return;if(e.type==='pointerdown'&&e.target.closest('[data-menu]'))return;const was=menu.value;menu.value='';if(e.type==='keydown'&&was==='account')accountButton.value?.focus()}
function toggle(which){menu.value=menu.value===which?'':which}
function journey(tab='journey'){journeyTab.value=tab;menu.value='';tierDialog.value.showModal()}
function menuKeys(e){const items=[...e.currentTarget.querySelectorAll('a,button')];const i=items.indexOf(document.activeElement);if(['ArrowDown','ArrowUp','Home','End'].includes(e.key)){e.preventDefault();items[e.key==='Home'?0:e.key==='End'?items.length-1:(i+(e.key==='ArrowDown'?1:-1)+items.length)%items.length]?.focus()}}
watch(()=>page.url,()=>menu.value='');
watch(journeyTab,()=>nextTick(()=>{const scroller=tierDialog.value?.querySelector('.journey-scroll');if(scroller)scroller.scrollTop=0}));
onMounted(()=>{observer=new ResizeObserver(()=>document.documentElement.style.setProperty('--header-height',header.value.offsetHeight+'px'));observer.observe(header.value);document.addEventListener('pointerdown',closeMenu);document.addEventListener('keydown',closeMenu)});
onUnmounted(()=>{observer?.disconnect();document.removeEventListener('pointerdown',closeMenu);document.removeEventListener('keydown',closeMenu)});
const practice=[['Maki Mentor','/practice?mode=tutor'],['Wasabi Rush','/practice?mode=exam'],['Roll Call','/library'],['Bento Builder','/exams']];
const social=[['Sushi Passport','/passport'],['Leaderboard','/leaderboard']];
</script>
<template><div class="app-shell"><header ref="header" class="sticky studio-header"><div class="topbar">
<Link href="/" class="brand"><img :src="art.logo" alt="SUSHI"><span>SUSHI<small>Clerks Exam Studio</small></span></Link>
<button class="rank rank-compact" @click="journey()" aria-label="View your sushi journey"><Avatar :avatar="community?.profile.avatar" size="small"/><span><strong>{{rank?.name}}</strong><small>{{rank?.count}} completed · {{rank?.remaining}} to next tier</small><span class="meter"><i :style="{width:rank?.percent+'%'}"></i></span></span></button>
<div class="header-actions"><Link href="/passport" class="streak-pill" :aria-label="community?.habits.current+' study-day streak'"><strong>🔥 {{community?.habits.current}}</strong><small>day streak</small></Link>
<button class="stamp-button" @click="journey('crew')" aria-label="View achievement crew">✿ <strong>{{community?.badge_count}}<small> / 45</small></strong></button>
<div class="account" data-menu><button ref="accountButton" class="profile-trigger" @click="toggle('account')" :aria-expanded="menu==='account'" aria-controls="account-menu" aria-label="Account menu"><Avatar :avatar="community?.profile.avatar" size="small"/><span>{{community?.profile.display_name}}</span><span aria-hidden="true">⌄</span></button>
<div v-if="menu==='account'" id="account-menu" class="dropdown account-dropdown" @keydown="menuKeys"><strong>{{community?.profile.display_name}}</strong><Link href="/profile">My Profile</Link><Link href="/profile#closet">Character Closet</Link><Link href="/settings">Settings</Link><Link href="/password">Change Password</Link><Link v-if="page.props.user.role==='admin'" href="/admin">Head Chef</Link><button @click="router.post('/logout')">Sign Out</button></div></div></div></div>
<nav aria-label="Main navigation" class="studio-nav"><Link href="/" :class="{active:page.url==='/'}">Counter</Link><Link href="/fresh-catch" :class="{active:page.url.startsWith('/fresh-catch')}">Fresh Catch</Link><Link href="/flashcards" :class="{active:page.url.startsWith('/flashcards')}">Memory Maki</Link>
<div v-for="[id,label,links] in [['practice','Practice',practice],['community','Community',social]]" :key="id" class="nav-menu" data-menu><button @click="toggle(id)" :aria-expanded="menu===id" :class="{active:links.some(x=>page.url===x[1])}">{{label}} ⌄</button><div v-if="menu===id" class="dropdown" @keydown="menuKeys"><Link v-for="[name,url] in links" :key="url" :href="url">{{name}}</Link></div></div>
<Link href="/progress" :class="{active:page.url.startsWith('/progress')}">My Progress</Link></nav></header>
<main class="main"><p v-if="page.props.flash" class="notice" role="status">{{page.props.flash}}</p><Errors :errors="page.props.errors"/><slot/></main><Footer/>
<dialog ref="tierDialog" class="journey-dialog" @click="e=>{if(e.target===tierDialog)tierDialog.close()}"><div class="journey-header"><div><p class="eyebrow">Your collection, your pace</p><h2>Your sushi journey</h2></div><button @click="tierDialog.close()" aria-label="Close your sushi journey">✕</button><div class="journey-tabs"><button :class="{selected:journeyTab==='journey'}" @click="journeyTab='journey'">Journey</button><button :class="{selected:journeyTab==='crew'}" @click="journeyTab='crew'">Achievement Crew · {{community?.badge_count}} / 45</button></div></div>
<div class="journey-scroll" tabindex="0"><template v-if="journeyTab==='journey'"><div class="journey-profile"><Avatar :avatar="community?.profile.avatar" size="large"/><div><h3>{{rank?.name}}</h3><p>{{rank?.count}} unique questions completed. {{rank?.remaining}} to {{rank?.next}}.</p><div class="meter"><i :style="{width:rank?.percent+'%'}"></i></div></div></div><p>Every 200 unique completed questions earns another tier. Checked answers and rated flashcards share the count. Repeats are practice; new questions keep your journey growing.</p>
<section class="journey-frames"><h3>Your portrait frames</h3><p>Bronze, Silver, Gold, and Sakura decorate your portrait. Your sushi tier keeps its own name.</p><div class="frame-choices"><div v-for="f in rank?.frames" :key="f.id" :class="{selected:community?.profile.avatar.frame===f.id}"><Avatar :avatar="{...community?.profile.avatar,frame:f.id}"/><strong>{{f.name}}</strong><small>{{!f.unlocked?'At '+f.at+' questions':community?.profile.avatar.frame===f.id?'Equipped':'Unlocked'}}</small></div></div><Link href="/profile#frames" class="button spaced" @click="tierDialog.close()">Choose a portrait frame</Link></section>
<h3 class="spaced">Your sushi tiers</h3><p>26 unique names from Rice Rookie to Omakase Master at 5,000 questions. The journey continues every 200 questions beyond that.</p><ol class="rank-stages"><li v-for="t in rank?.tiers" :key="t.at" :class="{earned:rank.count>=t.at}"><Avatar :avatar="community?.profile.avatar" /><div><strong>{{t.name}}</strong><small>{{t.at.toLocaleString()}} questions</small></div><span v-if="rank.count>=t.at">✓</span></li></ol></template>
<BadgeCrew v-else :badges="community?.badges||[]" compact/></div></dialog></div></template>
